import { cookies, headers } from 'next/headers'

function getPreferredLanguage(acceptLanguage: string | null): string {
  if (!acceptLanguage) return 'Not specified'

  // Parse entries like "en-US,en;q=0.9,fr;q=0.8" and pick the highest q value.
  const [best] = acceptLanguage
    .split(',')
    .map((part) => {
      const [tag, ...params] = part.trim().split(';')
      const q = params.find((p) => p.trim().startsWith('q='))
      return { tag: tag.trim(), q: q ? parseFloat(q.trim().slice(2)) : 1 }
    })
    .filter(({ tag, q }) => tag && tag !== '*' && !Number.isNaN(q) && q > 0)
    .sort((a, b) => b.q - a.q)

  return best?.tag ?? 'Not specified'
}

export default async function UserPreferences() {
  const cookieStore = await cookies()
  const headersList = await headers()

  const theme = cookieStore.get('theme')?.value || 'light'
  const language = getPreferredLanguage(headersList.get('accept-language'))

  return (
    <section>
      <p>
        Current theme: <strong>{theme}</strong>
      </p>
      <p>
        Preferred language: <strong>{language}</strong>
      </p>
    </section>
  )
}

